// File and folder names can contain anything, including shell syntax, so every
// value is single-quoted, folders are validated, and only files we listed are moved.
const q = (s) => "'" + String(s).replace(/'/g, `'\\''`) + "'";
const directory = $('Set Variables').first().json.directory.replace(/\/+$/, '');
const listed = $('Files and Folders to Array').first().json;
const files = new Set(listed.files);
const folders = new Set(listed.folders.map((f) => f.replace(/\/$/, '')));
const safeFolder = /^[A-Za-z0-9][A-Za-z0-9 _.-]{0,63}$/;
const moved = new Set();
const out = [];

for (const item of $input.all()) {
  let folder = String(item.json.folder ?? '').trim();
  if (!folders.has(folder) && !safeFolder.test(folder)) folder = 'misc';
  const toMove = (item.json.files ?? []).filter((f) => files.has(f) && !moved.has(f));
  if (!toMove.length) continue;
  toMove.forEach((f) => moved.add(f));

  const dest = `${directory}/${folder}`;
  const lines = [`mkdir -p -- ${q(dest)} || exit 1`];
  for (const f of toMove) {
    const dot = f.lastIndexOf('.');
    const [base, ext] = dot > 0 ? [f.slice(0, dot), f.slice(dot)] : [f, ''];
    lines.push(
      `src=${q(`${directory}/${f}`)}; base=${q(`${dest}/${base}`)}; ext=${q(ext)}`,
      // If the subdirectory already has a file with this name, add a number: report-1.pdf, report-2.pdf, ...
      'target="$base$ext"; n=1',
      'while [ -e "$target" ]; do target="$base-$n$ext"; n=$((n+1)); done',
      'mv -n -- "$src" "$target"',
    );
  }
  out.push({ json: { folder, files: toMove, command: lines.join('\n') } });
}

return out;
